use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdecltrait! {
# [doc = " Types implementing this trait can be parsed from a positional numeral system with radix 10"] pub trait FromRadix10 : Sized { # [doc = " Parses an integer from a slice."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use atoi::FromRadix10;"] # [doc = " // Parsing to digits from a slice"] # [doc = " assert_eq!((42,2), u32::from_radix_10(b\"42\"));"] # [doc = " // Additional bytes after the number are ignored"] # [doc = " assert_eq!((42,2), u32::from_radix_10(b\"42 is the answer to life, the universe and everything\"));"] # [doc = " // (0,0) is returned if the slice does not start with a digit"] # [doc = " assert_eq!((0,0), u32::from_radix_10(b\"Sadly we do not know the question\"));"] # [doc = " // While signed integer types are supported..."] # [doc = " assert_eq!((42,2), i32::from_radix_10(b\"42\"));"] # [doc = " // Signs are not allowed (even for signed integer types)"] # [doc = " assert_eq!((0,0), i32::from_radix_10(b\"-42\"));"] # [doc = " // Leading zeros are allowed"] # [doc = " assert_eq!((42,4), u32::from_radix_10(b\"0042\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Return"] # [doc = ""] # [doc = " Returns a tuple with two numbers. The first is the integer parsed or zero, the second is the"] # [doc = " index of the byte right after the parsed number. If the second element is zero the slice"] # [doc = " did not start with an ASCII digit."] fn from_radix_10 (_ : & [u8]) -> (Self , usize) ; }
}